/* Sample reports are generated by the real 101-answer browser test workflow.
 * Never promise a file is present merely because the link exists in HTML.
 */
(()=>{'use strict';
const paths=[...new Set([...document.querySelectorAll('[data-sample-status]')].map(x=>x.getAttribute('data-sample-status')).filter(Boolean))];
if(!paths.length)return;
async function verify(path){
 const indicators=[...document.querySelectorAll('[data-sample-status]')].filter(el=>el.getAttribute('data-sample-status')===path);
 const links=[...document.querySelectorAll('a[data-sample-pdf]')].filter(el=>el.getAttribute('href')===path);
 try{
  const response=await fetch(path,{method:'HEAD',cache:'no-store'});
  const kind=(response.headers.get('content-type')||'').toLowerCase();
  if(!response.ok||!kind.includes('pdf'))throw Error('Not yet published');
  indicators.forEach(el=>{el.textContent='PDF available · open or download';el.dataset.available='true'});
  links.forEach(el=>{el.removeAttribute('aria-disabled');el.removeAttribute('tabindex')});
 }catch{
  indicators.forEach(el=>{el.textContent='This PDF is not available on the current published build. The report guide remains accessible.';el.dataset.available='false'});
  links.forEach(el=>{el.setAttribute('aria-disabled','true');el.setAttribute('tabindex','-1');el.addEventListener('click',event=>event.preventDefault())});
 }
}
paths.forEach(path=>void verify(path));
})();
